      const mockStream = (async function* () {

        yield {

          type: 'text_delta',

          delta: 'Tier: low\nConfidence: high\nReasoning: Simple.',

        };

      })();

      vi.mocked(streamSimple).mockReturnValue(mockStream as any);

      const result = await runClassifier(

