          return (async function* () {

            yield { type: 'error', error: { errorMessage: 'rate limited' } };

          })();

        }

        return (async function* () {

          yield {

            type: 'text_delta',

            delta: 'Tier: medium\nConfidence: medium\nReasoning: Normal.',

          };

