            };
          })() as any) as any,
      );

      child.options.streamSimple(makeModel(), makeContext());
      await sleep(50);

      // pi-subagents' 10-minute cleanup timer evicts the completed
      // subagent: session_shutdown lands on the child closure mid-turn.
