  if (preferDown) {
    // Budget path: try lower tiers first to respect the cap
    for (let i = startIdx - 1; i >= 0; i--) {
      if (profile[order[i]]) return order[i];
    }
    // Last resort: fall up (e.g. high-only profile)
    for (let i = startIdx + 1; i < order.length; i++) {
      if (profile[order[i]]) return order[i];
