      if (result) return result;

    } catch (error) {

      if (stalled) options.onStall?.(ref, options.timeoutMs);

      void error;

    } finally {

      clearTimeout(timer);

      options.signal?.removeEventListener('abort', propagateAbort);

    }

  }

  return undefined;

};



